import numpy as np
import pytest

from chirp_analysis import analyze, generate_chirp


@pytest.fixture(scope="module")
def chirp_result():
    _, x = generate_chirp(duration=4.0, fs=4000.0, f0=100.0, f1=400.0,
                          amplitude=1.0, noise_sigma=0.5, seed=5)
    return analyze(x, fs=4000.0)


def test_sweep_rate_within_2_percent(chirp_result):
    expected_rate = (400.0 - 100.0) / 4.0  # 75 Hz/s
    assert abs(chirp_result["slope"] - expected_rate) / expected_rate < 0.02


def test_intercept_within_3_hz(chirp_result):
    assert abs(chirp_result["intercept"] - 100.0) < 3.0


def test_residual_mad_under_4_hz(chirp_result):
    assert chirp_result["mad"] < 4.0


def test_pure_tone_slope_near_zero():
    fs = 4000.0
    n = int(4.0 * fs)
    t = np.arange(n) / fs
    rng = np.random.default_rng(5)
    x = np.sin(2.0 * np.pi * 250.0 * t) + rng.normal(0.0, 0.5, n)
    res = analyze(x, fs)
    assert abs(res["slope"]) < 0.5
